<?php
namespace SerbenConnect\Services; use SerbenConnect\API\Client;
if(!defined('ABSPATH')){exit;} final class RecorrenciaService{private $c;function __construct(?Client $c=null){$this->c=$c?:new Client();}function getPagador(string $d):array{return $this->c->integrationGet('recorrencia','Pagadores/getPagadorByDocumento',['documento'=>preg_replace('/\D+/','',$d)]);}function criarPagador(array $p):array{return $this->c->integrationPost('recorrencia','Pagadores/criarPagador',$p);}function editarPagador(array $p):array{return $this->c->integrationPut('recorrencia','Pagadores/editarPagador',$p);}function gerarCobranca(array $p,string $key=''):array{return $this->c->integrationPost('recorrencia','Vendas/gerarNovaCobranca',$p,$key!==''?['Idempotency-Key'=>$key]:[]);}function listarCobrancas(int $page=1,int $limit=20):array{return $this->c->integrationGet('recorrencia','Vendas/getInfosCobranca',['page'=>max(1,$page),'limit'=>min(100,max(1,$limit))]);}function getCobranca(int $id):array{return $this->c->integrationGet('recorrencia','Vendas/getInfosCobrancaPorId',['id_cobranca'=>$id]);}function faturas(int $id):array{return $this->c->integrationGet('recorrencia','Vendas/getFaturasPorIdCobranca',['id_cobranca'=>$id]);}function cancelarCobranca(array $p):array{return $this->c->integrationPost('recorrencia','Vendas/cancelarCobrancaPorId',$p);}}
